import { forwardRef, type HTMLAttributes, type ReactNode } from "react";

import { cn } from "@/lib/cn";

/** Supported AlertTone values. */
export type AlertTone =
  | "neutral"
  | "primary"
  | "secondary"
  | "accent"
  | "success"
  | "info"
  | "warning"
  | "error";

const alertToneClasses = {
  neutral: "alert-neutral",
  primary: "alert-primary",
  secondary: "alert-secondary",
  accent: "alert-accent",
  success: "alert-success",
  info: "alert-info",
  warning: "alert-warning",
  error: "alert-error",
} satisfies Record<AlertTone, string>;

/** Props accepted by Alert. */
export type AlertProps = {
  action?: ReactNode;
  description?: ReactNode;
  title?: ReactNode;
  tone?: AlertTone;
} & Omit<HTMLAttributes<HTMLDivElement>, "title">;

/** A caller-labelled alert presentation. */
export const Alert = forwardRef<HTMLDivElement, AlertProps>(function Alert(
  {
    action,
    children,
    className,
    description,
    title,
    tone = "neutral",
    ...props
  },
  ref,
) {
  return (
    <div
      {...props}
      className={cn("alert caps-alert", alertToneClasses[tone], className)}
      data-tone={tone}
      role={props.role ?? "alert"}
      ref={ref}
    >
      <div className="min-w-0 flex-1">
        {title ? <h3 className="font-semibold">{title}</h3> : null}
        {description ? <p className="text-sm">{description}</p> : null}
        {children}
      </div>
      {action ? <div className="shrink-0">{action}</div> : null}
    </div>
  );
});

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

.caps-alert.border:
var(--border) solid
      color-mix(
        in oklch,
        var(--color-base-content) calc(18% + (1 - var(--depth)) * 82%),
        var(--color-base-200)
      )

.caps-alert.boxShadow:
var(
      --stipe-shadow-raised,
      inset 0 calc(var(--depth) * 1px) 0
        color-mix(in oklch, white calc(var(--depth) * 45%), transparent),
      inset 0 calc(var(--depth) * -2px) 0
        color-mix(
          in oklch,
          var(--color-base-content) calc(var(--depth) * 12%),
          transparent
        ),
      0 calc(var(--depth) * 2px) 0
        color-mix(
          in oklch,
          var(--color-base-content) calc(var(--depth) * 16%),
          transparent
        )
    )
